for code, L in LANGS.items():
    if "photo-resizer" in L["tools"]:
        L["tools"]["photo-resizer"]["tr"].append('<option value="pp" selected>')
    L["common_rep"] = list(zip(COMMON_KEYS, L["common"]))
    for slug, t in L["tools"].items():
        keys = KEYS[slug]
        assert len(keys) == len(t["tr"]), f"{code}/{slug}: {len(keys)} keys vs {len(t['tr'])} translations"
        t["rep"] = list(zip(keys, t["tr"]))

